func newAuditedServer(t *testing.T) *testServer {
	t.Helper()
	return newAuditedServerWith(t, testBrowser())
}

// newAuditedServerWith is newAuditedServer with layer 1 chosen by the caller,
// which is what browser_test.go needs and no test of the API door does: that
// door reads no assertion, so the validator behind it never runs.
func newAuditedServerWith(t *testing.T, browser layer1) *testServer {
	t.Helper()
	return newAuditedServerOn(t, testConfig(loopbackListen), browser)
}

// newAuditedServerOn is newAuditedServerWith with the Config chosen as well,
// which the sign-in suite needs and nothing before it did.
//
// Adjusting the fixture's Config after construction — settingsOn's shape — is
// enough for anything a handler reads per request, and is not enough here: which
// routes a daemon registers is decided once, at construction, from the door it
// was built with (M12/T004). A fixture that changed the Config afterwards would
// be making claims about a daemon that never existed.
func newAuditedServerOn(t *testing.T, cfg *config.Config, browser layer1) *testServer {
	t.Helper()

	buf := &syncSink{}
	fixture := newSessionFixture(t)
	s, err := newServer(
		cfg,
		net.Listen,
		testAuth(t),
		browser,
		audit.NewTo(buf, func() time.Time { return testTime }),
		fixture.mgr,
		testLimiter(t, cfg.CreateRatePerMin, fixedClock{at: testTime}),
	)
	if err != nil {
		t.Fatalf("newServer = _, %v; want a server", err)
	}

	pinClock(s)
	ts := &testServer{Server: s, sink: buf, fixture: fixture}
	s.report = func(err error) { ts.failed = append(ts.failed, err) }
	return ts
}

// syncSink is the buffer the trail is written into, guarded.
//
// A plain bytes.Buffer served every milestone 1 test, because a request there
// has written its record by the time the response the test is holding exists.
// The stream broke that: its record is written at the open (FR-016a) and the
// handler goes on running on net/http's own goroutine for as long as the browser
// watches, so a test that reads the trail while a stream is open is reading a
// buffer another goroutine wrote into with nothing ordering the two. The lock is
// that ordering. Without it the suite carries a data race that only -race
// reports, and only for the tests bold enough to look while a stream is live.
type syncSink struct {
	mu  sync.Mutex
	buf bytes.Buffer
}

func (s *syncSink) Write(p []byte) (int, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.buf.Write(p)
}

func (s *syncSink) String() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.buf.String()
}

// records decodes everything written to the trail so far.
func (s *testServer) records(t *testing.T) []map[string]any {
	t.Helper()

	var out []map[string]any
	for _, line := range strings.Split(strings.TrimSpace(s.sink.String()), "\n") {
		if line == "" {
			continue
		}
		var rec map[string]any
		if err := json.Unmarshal([]byte(line), &rec); err != nil {
			t.Fatalf("audit line %q is not JSON: %v", line, err)
		}
		out = append(out, rec)
	}
	return out

	return out
}

// only asserts that a request produced exactly one record — FR-041's whole
// claim — and returns it.
func (s *testServer) only(t *testing.T) map[string]any {
	t.Helper()

	got := s.records(t)
	if len(got) != 1 {
		t.Fatalf("the request emitted %d audit records (%v); FR-041 requires exactly one", len(got), got)
	}
	return got[0]
}

